def plan_fit(params_b, vram_gb, context_tokens=0, kv_gb_per_1k=0.0, overhead=0.20):
    bytes_per = [("fp16", 2.0), ("int8", 1.0), ("int4", 0.5)]
    kv = kv_gb_per_1k * context_tokens / 1000.0
    total = None
    for name, width in bytes_per:
        weights = params_b * 1e9 * width / 1024 ** 3
        total = (weights + kv) * (1 + overhead)
        if total <= vram_gb:
            return {"quant": name, "gb": total}
    return {"quant": None, "gb": total}
